 void menu(View anchor){PopupMenu p=new PopupMenu(this,anchor);String[] items={"Search in book","Table of contents","Bookmarks","Add bookmark","Stylus tools","Zoom in","Zoom out","Reset zoom","Share book"};for(String s:items)p.getMenu().add(s);if(kind.equals("EPUB"))p.getMenu().add("Vertical scrolling").setCheckable(true).setChecked(epubVertical);p.setOnMenuItemClickListener(item->{switch(item.getTitle().toString()){case "Vertical scrolling":setEpubVertical(!epubVertical);break;case "Search in book":search();break;case "Table of contents":outline();break;case "Bookmarks":bookmarks();break;case "Add bookmark":getPreferences(0).edit().putString("bookmarks:"+uri,getPreferences(0).getString("bookmarks:"+uri,"")+pageIndex+",").apply();AppNotice.makeText(this,"Page bookmarked",Toast.LENGTH_SHORT).show();break;case "Stylus tools":stylus=!stylus;penHost.setVisibility(stylus?View.VISIBLE:View.GONE);if(!stylus)surface.setTool(0);break;case "Zoom in":if(pdfZoom!=null)pdfZoom.setZoom(pdfZoom.zoom*1.25f);else surface.zoom(1.25f);break;case "Zoom out":if(pdfZoom!=null)pdfZoom.setZoom(pdfZoom.zoom*.8f);else surface.zoom(.8f);break;case "Reset zoom":if(pdfZoom!=null)pdfZoom.setZoom(1);else surface.reset();break;case "Share book":share();break;}return true;});p.show();}
