  Runnable request=()->{int selected=slider.getProgress(),token=++revision[0];label.setText("Page "+(selected+1)+" of "+pageCount+"  ·  "+Math.round((selected+1)*100f/pageCount)+"%");preview.setAlpha(.45f);if(pending[0]!=null)handler.removeCallbacks(pending[0]);pending[0]=()->{if(closed[0]||worker.isShutdown())return;worker.execute(()->{if(closed[0]||token!=revision[0]||document==null)return;Bitmap bitmap=null;try{Page page=document.loadPage(selected);try{com.artifex.mupdf.fitz.Rect bounds=page.getBounds();float ratio=(bounds.y1-bounds.y0)/Math.max(1,bounds.x1-bounds.x0);int width=Math.min(900,Math.max(360,getResources().getDisplayMetrics().widthPixels));if(width*width*ratio>1500000)width=(int)Math.sqrt(1500000/ratio);bitmap=AndroidDrawDevice.drawPageFitWidth(page,width);}finally{page.destroy();}Bitmap ready=bitmap;runOnUiThread(()->{if(closed[0]||token!=revision[0]||isDestroyed()){ready.recycle();return;}preview.setImageBitmap(ready);preview.setAlpha(1);Bitmap old=shown[0];shown[0]=ready;if(old!=null)old.recycle();});}catch(Exception|OutOfMemoryError e){if(bitmap!=null)bitmap.recycle();runOnUiThread(()->{if(!closed[0]&&token==revision[0]){label.setText("Page "+(selected+1)+" — preview unavailable");preview.setAlpha(1);}});}});};handler.postDelayed(pending[0],120);};
