  dialog.setContentView(panel);dialog.setOnDismissListener(d->{previewDialog=null;closed[0]=true;revision[0]++;if(pending[0]!=null)handler.removeCallbacks(pending[0]);preview.setImageDrawable(null);if(shown[0]!=null){shown[0].recycle();shown[0]=null;}});dialog.show();Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setLayout(getResources().getDisplayMetrics().widthPixels-dp(24),(int)(getResources().getDisplayMetrics().heightPixels*.78f));window.setGravity(Gravity.BOTTOM);WindowManager.LayoutParams params=window.getAttributes();params.y=dp(12);window.setAttributes(params);}slider.setProgress(pageIndex);request.run();
