 void bookmarks(){ArrayList<String> labels=new ArrayList<>();ArrayList<Integer> pages=new ArrayList<>();for(String p:getPreferences(0).getString("bookmarks:"+uri,"").split(","))try{int n=Integer.parseInt(p);pages.add(n);labels.add("Page "+(n+1));}catch(Exception ignored){}new AppDialog.Builder(this).setTitle("Bookmarks").setItems(labels.isEmpty()?new String[]{"No bookmarks yet"}:labels.toArray(new String[0]),(d,n)->{if(!pages.isEmpty())go(pages.get(n));}).setNegativeButton("Close",null).show();}
 void search(){EditText input=new EditText(this);input.setSingleLine();new AppDialog.Builder(this).setTitle("Search in book").setView(input).setPositiveButton("Search",(d,n)->{String q=input.getText().toString().trim();if(q.isEmpty())return;busy.setVisibility(View.VISIBLE);worker.execute(()->{ArrayList<Integer> result=new ArrayList<>();try{for(int i=0;i<pageCount;i++){Page page=document.loadPage(i);try{if(page.search(q).length>0)result.add(i);}finally{page.destroy();}if(result.size()>=100)break;}runOnUiThread(()->{busy.setVisibility(View.GONE);String[] labels=result.stream().map(p->"Match on page "+(p+1)).toArray(String[]::new);new AppDialog.Builder(this).setTitle(result.size()+" matching pages").setItems(labels,(dd,nn)->go(result.get(nn))).setNegativeButton("Close",null).show();});}catch(Exception e){fail("Search could not be completed");}});}).setNegativeButton("Cancel",null).show();}
