 @Override protected void onPause(){if(surface!=null)surface.saveInk();if(stack!=null)for(int i=0;i<stack.getChildCount();i++)((ReaderSurface)stack.getChildAt(i)).saveInk();super.onPause();}
 @Override protected void onDestroy(){if(previewDialog!=null)previewDialog.dismiss();typographyVersion++;if(typographyTask!=null)handler.removeCallbacks(typographyTask);generation++;worker.execute(()->{if(document!=null){document.destroy();document=null;}if(styledEpub!=null)styledEpub.delete();});worker.shutdown();super.onDestroy();}
 private class PageHolder extends RecyclerView.ViewHolder {
  final ReaderSurface page;int token;
  PageHolder(ReaderSurface view){super(view);page=view;}
 }
 private class PageStack extends RecyclerView.Adapter<PageHolder> {
  @Override public int getItemCount(){return pageCount;}
  @Override public PageHolder onCreateViewHolder(ViewGroup parent,int type){
   ReaderSurface page=new ReaderSurface();
   page.setLayoutParams(new RecyclerView.LayoutParams(-1,kind.equals("EPUB")?Math.max(1,stack.getHeight()):Math.round(parent.getResources().getDisplayMetrics().widthPixels*1.414f)));
   return new PageHolder(page);
  }
  @Override public void onBindViewHolder(PageHolder holder,int position){
   int token=++holder.token;
   holder.page.saveInk();holder.page.displayed=-1;
   if(holder.page.bitmap!=null){holder.page.bitmap.recycle();holder.page.bitmap=null;holder.page.invalidate();}
   worker.execute(()->{
    if(document==null||isDestroyed())return;
    try{
     Page page=document.loadPage(position);Bitmap bitmap;
     try{
      com.artifex.mupdf.fitz.Rect bounds=page.getBounds();
      float aspect=(bounds.y1-bounds.y0)/Math.max(1,bounds.x1-bounds.x0);
      int width=Math.min(1440,Math.max(600,getResources().getDisplayMetrics().widthPixels));
      if(width*width*aspect>3000000)width=(int)Math.sqrt(3000000/aspect);
      bitmap=AndroidDrawDevice.drawPageFitWidth(page,width);
     }finally{page.destroy();}
     runOnUiThread(()->{
      if(isDestroyed()||holder.token!=token){bitmap.recycle();return;}
      int viewWidth=stack.getWidth()>0?stack.getWidth():getResources().getDisplayMetrics().widthPixels;
      ViewGroup.LayoutParams lp=holder.page.getLayoutParams();lp.width=viewWidth;lp.height=kind.equals("EPUB")?stack.getHeight():Math.round((viewWidth-dp(16))*bitmap.getHeight()/(float)bitmap.getWidth())+dp(16);holder.page.setLayoutParams(lp);
      holder.page.show(bitmap,position);if(kind.equals("PDF")&&position==pageIndex&&(pdfZoom==null||pdfZoom.zoom<=1.01f)){int viewport=stack.getHeight(),pageHeight=lp.height;int top=Math.max(dp(21),(viewport-pageHeight)/2-dp(36));int bottom=Math.max(dp(21),viewport-pageHeight-top);if(stack.getPaddingTop()!=top||stack.getPaddingBottom()!=bottom)stack.setPadding(0,top,0,bottom);}
     });
    }catch(Exception|OutOfMemoryError e){fail("Page "+(position+1)+" could not be rendered.");}
   });
  }
  @Override public void onViewRecycled(PageHolder holder){holder.token++;holder.page.saveInk();holder.page.displayed=-1;if(holder.page.bitmap!=null){holder.page.bitmap.recycle();holder.page.bitmap=null;}}
 }
 private class Stroke {int tool;ArrayList<PointF> points=new ArrayList<>();Stroke(int t){tool=t;}}
 private class ReaderSurface extends View {
  Bitmap bitmap;int displayed=-1,tool=0;float scale=1,panX=0,panY=0,lastX,lastY;RectF pageRect=new RectF();ArrayList<Stroke> strokes=new ArrayList<>(),undone=new ArrayList<>();Stroke active;Paint paint=new Paint(3);ScaleGestureDetector pinch;
  ReaderSurface(){super(ReaderActivity.this);setBackgroundColor(PAPER);pinch=new ScaleGestureDetector(ReaderActivity.this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){zoom(d.getScaleFactor());return true;}});setContentDescription("Book page. Pinch to zoom, drag to pan, swipe to turn pages.");}
  void show(Bitmap b,int page){Bitmap old=bitmap;bitmap=b;displayed=page;reset();loadInk();if(old!=null)old.recycle();invalidate();}
  void setTool(int t){selectedTool=t;tool=t;}
  void reset(){scale=1;panX=panY=0;invalidate();}
  void zoom(float factor){scale=Math.max(1,Math.min(5,scale*factor));invalidate();}
  void undo(){if(!strokes.isEmpty()){undone.add(strokes.remove(strokes.size()-1));saveInk();invalidate();}}
  void redo(){if(!undone.isEmpty()){strokes.add(undone.remove(undone.size()-1));saveInk();invalidate();}}
  @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);if(bitmap==null)return;float fit=kind.equals("EPUB")?(getWidth()-dp(currentType().left+currentType().right))/(float)bitmap.getWidth():Math.min((getWidth()-dp(16))/(float)bitmap.getWidth(),(getHeight()-dp(16))/(float)bitmap.getHeight());float width=bitmap.getWidth()*fit*scale,height=bitmap.getHeight()*fit*scale;float top=kind.equals("EPUB")?dp(currentType().top)+panY:(getHeight()-height)/2+panY;float left=kind.equals("EPUB")?dp(currentType().left)+panX:(getWidth()-width)/2+panX;pageRect.set(left,top,left+width,top+height);paint.setColor(AppTheme.dark?AppTheme.background:Color.WHITE);if(kind.equals("EPUB"))canvas.drawRect(0,0,getWidth(),getHeight(),paint);else canvas.drawRect(pageRect,paint);paint.setColorFilter(AppTheme.dark?nightPageFilter():null);canvas.drawBitmap(bitmap,null,pageRect,paint);paint.setColorFilter(null);canvas.save();canvas.clipRect(pageRect);for(Stroke s:strokes){paint.setStyle(Paint.Style.STROKE);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);paint.setColor(s.tool==2?0x80FFF9BD:s.tool==3?0xffE89090:0xff28467C);paint.setStrokeWidth(dp(s.tool==2?14:2)*scale);Path path=new Path();for(int i=0;i<s.points.size();i++){PointF p=s.points.get(i);float x=pageRect.left+p.x*pageRect.width(),y=pageRect.top+p.y*pageRect.height();if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}canvas.drawPath(path,paint);}paint.setStyle(Paint.Style.FILL);canvas.restore();}
  float startX,startY;@Override public boolean onTouchEvent(android.view.MotionEvent e){if(stack!=null&&e.getToolType(0)==android.view.MotionEvent.TOOL_TYPE_STYLUS)getParent().requestDisallowInterceptTouchEvent(true);if(stack==null)pinch.onTouchEvent(e);float x=e.getX(),y=e.getY();tool=selectedTool;boolean ink=tool>0&&e.getToolType(0)==android.view.MotionEvent.TOOL_TYPE_STYLUS;if(e.getActionMasked()==android.view.MotionEvent.ACTION_DOWN){lastX=startX=x;lastY=startY=y;if(ink&&pageRect.contains(x,y)){undone.clear();active=new Stroke(tool);strokes.add(active);}}if(active!=null){float px=(x-pageRect.left)/pageRect.width(),py=(y-pageRect.top)/pageRect.height();if(active.tool==3&&!active.points.isEmpty())py=active.points.get(0).y;active.points.add(new PointF(px,py));invalidate();}else if(e.getActionMasked()==android.view.MotionEvent.ACTION_MOVE&&scale>1&&!pinch.isInProgress()){panX+=x-lastX;panY+=y-lastY;invalidate();}if(e.getActionMasked()==android.view.MotionEvent.ACTION_UP){if(active!=null){active=null;saveInk();}else if(stack==null&&scale==1&&Math.abs(x-startX)>dp(65)&&Math.abs(y-startY)<dp(70))go(pageIndex+(x<startX?1:-1));performClick();}lastX=x;lastY=y;return true;}
  @Override public boolean performClick(){super.performClick();return true;}
  String key(){return "ink:"+uri+":"+fontSize+":"+displayed;}
  void saveInk(){if(displayed<0)return;JSONArray a=new JSONArray();try{for(Stroke s:strokes){JSONObject j=new JSONObject();JSONArray points=new JSONArray();for(PointF p:s.points)points.put(new JSONArray().put(p.x).put(p.y));j.put("tool",s.tool).put("points",points);a.put(j);}getPreferences(0).edit().putString(key(),a.toString()).apply();}catch(Exception ignored){}}
  void loadInk(){strokes.clear();undone.clear();try{JSONArray a=new JSONArray(getPreferences(0).getString(key(),"[]"));for(int i=0;i<a.length();i++){JSONObject j=a.getJSONObject(i);Stroke s=new Stroke(j.getInt("tool"));JSONArray pts=j.getJSONArray("points");for(int n=0;n<pts.length();n++){JSONArray p=pts.getJSONArray(n);s.points.add(new PointF((float)p.getDouble(0),(float)p.getDouble(1)));}strokes.add(s);}}catch(Exception ignored){}}
 }
